<script setup>
import { computed, ref } from 'vue';
import { Head, Link, router } from '@inertiajs/vue3';
import { Download, BookOpen, CheckCircle2, Clock3 } from 'lucide-vue-next';
import WorkspaceShell from '@/Layouts/WorkspaceShell.vue';
import Button from '@/Components/UI/Button.vue';
const props = defineProps({ organization: Object, filters: Object, departments: Array, stats: Object, enrollments: Object });
const filters = ref({ department: props.filters.department || '', status: props.filters.status || '', overdue: !!Number(props.filters.overdue || 0) });
const parameters = () => ({ department: filters.value.department || undefined, status: filters.value.status || undefined, overdue: filters.value.overdue ? 1 : undefined });
const apply = () => router.get('/organization/reports', parameters(), { preserveState: true, replace: true });
const exportUrl = computed(() => '/organization/reports/export?' + new URLSearchParams(Object.entries(props.filters).filter(([, value]) => value !== null && value !== '')).toString());
const date = value => value ? new Intl.DateTimeFormat(undefined, { day: 'numeric', month: 'short', year: 'numeric', timeZone: 'UTC' }).format(new Date(value)) : 'No deadline';
const selectClass = 'mt-2 w-full rounded-xl border border-surface-200 bg-white px-3 py-2.5 text-sm';
</script>
<template>
    <Head title="Organization learning report" />
    <WorkspaceShell workspace="organization">
        <div class="space-y-7">
            <header class="flex flex-wrap items-start justify-between gap-5"><div><p class="text-xs font-semibold uppercase tracking-widest text-primary-700">{{ organization.name }}</p><h1 class="mt-2 text-3xl font-display font-bold tracking-tight">See how your team is learning</h1><p class="mt-2 text-sm text-surface-500">Track course progress, completions and deadlines across your organization.</p></div><a :href="exportUrl" class="inline-flex items-center gap-2 rounded-xl border border-surface-200 bg-white px-4 py-2.5 text-sm font-semibold text-surface-700 hover:bg-surface-50"><Download class="h-4 w-4" />Export current report</a></header>
            <div class="grid grid-cols-1 gap-4 sm:grid-cols-3"><div v-for="metric in [{ label: 'Enrollments', value: stats.enrollments, icon: BookOpen }, { label: 'Completed courses', value: stats.completed, icon: CheckCircle2 }, { label: 'Active & overdue', value: stats.overdue, icon: Clock3 }]" :key="metric.label" class="rounded-2xl border border-surface-200 bg-white p-5"><div class="flex items-center justify-between text-surface-500"><p class="text-sm">{{ metric.label }}</p><component :is="metric.icon" class="h-5 w-5" /></div><p class="mt-3 text-3xl font-semibold">{{ metric.value }}</p><p class="mt-2 text-xs text-surface-400">Within the applied filters</p></div></div>
            <section class="overflow-hidden rounded-2xl border border-surface-200 bg-white">
                <form @submit.prevent="apply" class="flex flex-wrap items-end gap-4 border-b border-surface-100 p-5"><label class="min-w-40 flex-1 text-sm font-medium">Department<select v-model="filters.department" :class="selectClass"><option value="">All departments</option><option v-for="d in departments" :key="d.id" :value="d.id">{{ d.name }}</option></select></label><label class="min-w-40 flex-1 text-sm font-medium">Enrollment status<select v-model="filters.status" :class="selectClass"><option value="">All statuses</option><option value="active">Active</option><option value="completed">Completed</option><option value="suspended">Suspended</option><option value="expired">Expired</option></select></label><label class="flex min-h-11 items-center gap-2 text-sm"><input v-model="filters.overdue" type="checkbox" class="rounded border-surface-300 text-primary-600" />Only active, overdue courses</label><Button type="submit" variant="secondary">Apply filters</Button></form>
                <div class="overflow-x-auto"><table class="w-full text-left text-sm"><caption class="sr-only">Course enrollments for people in your organization</caption><thead class="bg-surface-50 text-xs text-surface-500"><tr><th scope="col" class="px-5 py-3 font-medium">Learner</th><th scope="col" class="px-5 py-3 font-medium">Course</th><th scope="col" class="px-5 py-3 font-medium">Progress</th><th scope="col" class="px-5 py-3 font-medium">Status</th><th scope="col" class="px-5 py-3 font-medium">Deadline</th></tr></thead><tbody class="divide-y divide-surface-100"><tr v-for="enrollment in enrollments.data" :key="enrollment.id"><td class="px-5 py-4"><p class="whitespace-nowrap font-medium">{{ enrollment.user.full_name }}</p><p class="mt-1 text-xs text-surface-500">{{ enrollment.user.email }}</p></td><td class="min-w-48 max-w-72 px-5 py-4">{{ enrollment.course?.title || 'Archived course' }}</td><td class="min-w-32 px-5 py-4"><p class="text-xs tabular-nums">{{ enrollment.progress_pct }}%</p><div class="mt-2 h-1.5 rounded-full bg-surface-100" aria-hidden="true"><div class="h-full rounded-full bg-primary-600" :style="{ width: `${Math.min(100, enrollment.progress_pct)}%` }" /></div></td><td class="px-5 py-4"><span :class="['rounded-full px-2.5 py-1 text-xs capitalize', enrollment.status === 'completed' ? 'bg-emerald-50 text-emerald-800' : 'bg-surface-100 text-surface-600']">{{ enrollment.status }}</span></td><td class="whitespace-nowrap px-5 py-4 text-xs text-surface-500">{{ date(enrollment.deadline) }}</td></tr></tbody></table></div>
                <div v-if="!enrollments.data.length" class="px-6 py-14 text-center"><BookOpen class="mx-auto h-9 w-9 text-surface-300" /><h2 class="mt-4 font-semibold">No enrollments match these filters</h2><p class="mt-2 text-sm text-surface-500">Try a different department or status. New learning activity will appear here.</p></div>
                <div class="flex items-center justify-between border-t border-surface-100 px-5 py-4 text-xs text-surface-500"><span>{{ enrollments.total }} enrollments · Page {{ enrollments.current_page }} of {{ enrollments.last_page }}</span><div class="flex gap-5"><Link v-if="enrollments.prev_page_url" :href="enrollments.prev_page_url" class="py-2 font-medium">Previous</Link><Link v-if="enrollments.next_page_url" :href="enrollments.next_page_url" class="py-2 font-medium">Next</Link></div></div>
            </section>
        </div>
    </WorkspaceShell>
</template>
